        // Builds a catalog subtree element carrying its source id token verbatim, so an IDREF inside the
        // subtree still names its target. These placeholder ids are re-minted by the insert transform; only
        // their internal consistency matters. Mirrors the ElRaw helper the product oracle tests use.
        private static ProjectElement ElRaw(string tag, string idToken, (string, string)[] attrs,
            params ProjectElement[] children)
        {
            ElementId? id = ElementId.TryParse(idToken, out ElementId parsed) ? parsed : null;
            ImmutableArray<(string, string)>.Builder bag =
                ImmutableArray.CreateBuilder<(string, string)>(attrs.Length + 1);
            bag.Add(("id", idToken));
            bag.AddRange(attrs);
            return new ProjectElement(tag, id, bag.ToImmutable(), children.ToImmutableArray());
        }
    }
